    int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} 
    @Override public void onCreate(Bundle b){super.onCreate(b);load();loadAppearance();getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);if(!notes.isEmpty())note=notes.get(0);current=0;buildHome();}
    @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){edgeDownX=event.getX();edgeDownY=event.getY();if(undoSnackbar!=null&&!touchInside(event,undoSnackbar))dismissUndoSnackbar();}else if(action==MotionEvent.ACTION_UP){float dx=event.getX()-edgeDownX,dy=event.getY()-edgeDownY;if(Math.abs(dx)>dp(80)&&Math.abs(dx)>Math.abs(dy)*1.3f){if(sideDrawerOverlay!=null){closeDrawer();return true;}if(screen==6){stepWalk(dx<0?1:-1);return true;}if(screen==0&&dx<0){showDrawer();return true;}if(edgeDownX<=dp(24)&&dx>0){handleBack();return true;}}}return super.dispatchTouchEvent(event);}
    boolean touchInside(MotionEvent event,View view){int[] xy=new int[2];view.getLocationOnScreen(xy);float x=event.getRawX(),y=event.getRawY();return x>=xy[0]&&x<=xy[0]+view.getWidth()&&y>=xy[1]&&y<=xy[1]+view.getHeight();}
    void dismissUndoSnackbar(){if(undoSnackbar!=null){View old=undoSnackbar;undoSnackbar=null;if(old.getParent() instanceof ViewGroup)((ViewGroup)old.getParent()).removeView(old);}}
    void showUndoSnackbar(String message,Runnable undoAction){dismissUndoSnackbar();FrameLayout host=findViewById(android.R.id.content);LinearLayout bar=row();bar.setPadding(dp(18),0,dp(10),0);bar.setBackground(shape(0xFF3B3B3B,12));bar.setElevation(dp(6));TextView label=text(message,14,Color.WHITE,false);bar.addView(label,new LinearLayout.LayoutParams(0,dp(52),1));TextView undoText=text("撤销",14,0xFFFF5A4F,true);undoText.setGravity(Gravity.CENTER);bar.addView(undoText,new LinearLayout.LayoutParams(dp(58),dp(52)));undoSnackbar=bar;bar.setOnClickListener(v->dismissUndoSnackbar());undoText.setOnClickListener(v->{dismissUndoSnackbar();undoAction.run();});FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,dp(52),Gravity.BOTTOM);lp.setMargins(dp(16),0,dp(16),dp(18));host.addView(bar,lp);}
    @Override public void onBackPressed(){handleBack();}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null||data.getData()==null)return;if(requestCode==REQUEST_EXPORT)writeBackup(data.getData());else if(requestCode==REQUEST_IMPORT)readBackup(data.getData());}
    @Override protected void onPause(){super.onPause();if(pendingDiskSave!=null){saveHandler.removeCallbacks(pendingDiskSave);pendingDiskSave=null;}getSharedPreferences("suiyi",0).edit().commit();}
    void handleBack(){if(screen==4){if(editorReturnScreen==3){editorReturnScreen=0;buildSearch(pendingSearch);}else if(editorReturnScreen==6)buildWalk();else buildHome();return;}if(screen==3){if(searchReturnScreen==4)buildEditor();else if(searchReturnScreen==2)buildTimeline();else if(searchReturnScreen==6)buildWalk();else buildHome();return;}if(screen==2||screen==5||screen==6){buildHome();return;}super.onBackPressed();}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size*fontScale);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);if(fontChoice==1)t.setTypeface(Typeface.SERIF,bold?Typeface.BOLD:Typeface.NORMAL);else if(fontChoice==2)t.setTypeface(Typeface.MONOSPACE,bold?Typeface.BOLD:Typeface.NORMAL);else if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    void loadAppearance(){SharedPreferences prefs=getSharedPreferences("suiyi",0);themeChoice=prefs.getInt("themeChoice",0);fontChoice=prefs.getInt("fontChoice",0);gridChoice=prefs.getInt("gridChoice",0);fontScale=prefs.getFloat("fontScale",1f);applyTheme();}
    void applyTheme(){if(themeChoice==1){bg=0xFFF0F1F3;ink=0xFF202124;muted=0xFF74777D;line=0xFFE1E3E6;}else if(themeChoice==2){bg=0xFFF1F6F3;ink=0xFF1D2922;muted=0xFF718077;line=0xFFDCE7DF;}else{bg=0xFFF7F7F7;ink=0xFF171717;muted=0xFF888888;line=0xFFEEEEEE;}}
    void saveAppearance(){getSharedPreferences("suiyi",0).edit().putInt("themeChoice",themeChoice).putInt("fontChoice",fontChoice).putInt("gridChoice",gridChoice).putFloat("fontScale",fontScale).apply();applyTheme();}
