    String glyph(String name){if(name.equals("搜索"))return "search";if(name.equals("撤销"))return "undo";if(name.equals("筛选"))return "filter";if(name.equals("返回"))return "back";if(name.equals("菜单"))return "menu";if(name.equals("更多"))return "more";if(name.equals("日历"))return "calendar";if(name.equals("列表视图"))return "clock";if(name.equals("收起日历"))return "collapse";if(name.equals("展开日历"))return "expand";return name;}
