    void addPreviewCard(LinearLayout list,Note item,String query){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(18),dp(14),dp(12),dp(16));card.setBackground(shape(item.pinned?0xFFFFFBF0:Color.WHITE,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);list.addView(card,cp);LinearLayout topLine=row();card.addView(topLine,new LinearLayout.LayoutParams(-1,dp(34)));if(!item.title.trim().isEmpty()){TextView heading=text(item.title,18,ink,true);if(!query.isEmpty())heading.setText(highlight(item.title,query));topLine.addView(heading,new LinearLayout.LayoutParams(0,-1,1));}else topLine.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));if(item.pinned){IconGlyph pin=new IconGlyph("pin",0xFFD39A22);topLine.addView(pin,new LinearLayout.LayoutParams(dp(20),dp(20)));}FrameLayout more=new FrameLayout(this);more.setContentDescription("笔记操作");IconGlyph moreIcon=new IconGlyph("moreHorizontal",muted);more.addView(moreIcon,new FrameLayout.LayoutParams(dp(22),dp(22),Gravity.CENTER));topLine.addView(more,new LinearLayout.LayoutParams(dp(36),dp(34)));more.setOnClickListener(v->showNoteActions(more,item));String snippetValue=searchPreview(item,query);TextView snippet=text(snippetValue,14,ink,false);snippet.setGravity(Gravity.TOP);snippet.setMaxLines(3);snippet.setEllipsize(android.text.TextUtils.TruncateAt.END);if(!query.isEmpty())snippet.setText(highlight(snippetValue,query));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(4);card.addView(snippet,sp);TextView meta=text(dateLabel(item.updatedAt),12,0xFFB0B0B0,false);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,dp(22));mp.topMargin=dp(10);card.addView(meta,mp);card.setOnClickListener(v->openNote(item,query));}
    String dateLabel(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);return String.format(Locale.CHINA,"%d月%d日 %02d:%02d:%02d",c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH),c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),c.get(Calendar.SECOND));}
    String timestampLabel(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);return String.format(Locale.CHINA,"%d年%d月%d日 %02d:%02d:%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH),c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),c.get(Calendar.SECOND));}
    void createNote(){editorReturnScreen=0;note=new Note();notes.add(0,note);current=0;isLinear=false;pendingSearch="";persist();buildEditor();}
    void openNote(Note target,String query){editorReturnScreen=screen;if(screen==6)walkReturnNote=target;current=notes.indexOf(target);if(current<0)current=0;note=target;pendingSearch=query==null?"":query;boolean blockHit=false;for(Block b:target.blocks)if(contains(b.text,pendingSearch)){blockHit=true;break;}isLinear=target.blocks.isEmpty()||(!pendingSearch.isEmpty()&&contains(target.text,pendingSearch)&&!blockHit);buildEditor();}
    void openSearch(String query){searchReturnScreen=screen;buildSearch(query);}
    void buildSearch(String query){screen=3;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(8),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));FrameLayout menu=iconButton("菜单",()->showDrawer());header.addView(menu,new LinearLayout.LayoutParams(dp(40),dp(42)));FrameLayout back=iconButton("返回",this::handleBack);header.addView(back,new LinearLayout.LayoutParams(dp(38),dp(42)));searchInput=new EditText(this);searchInput.setSingleLine(true);searchInput.setTextSize(16);searchInput.setTextColor(ink);searchInput.setHintTextColor(0xFFB0B0B0);searchInput.setHint("搜索笔记和标签");searchInput.setPadding(dp(14),0,dp(14),0);searchInput.setBackground(shape(Color.WHITE,22));searchInput.setText(query);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,dp(44),1);ep.leftMargin=dp(6);header.addView(searchInput,ep);TextView clear=text("×",22,muted,false);clear.setGravity(Gravity.CENTER);header.addView(clear,new LinearLayout.LayoutParams(dp(38),dp(42)));clear.setOnClickListener(v->searchInput.setText(""));searchResults=new FrameLayout(this);root.addView(searchResults,new LinearLayout.LayoutParams(-1,0,1));bottomNav(0);searchInput.addTextChangedListener(watch(v->{activeTagFilter="";updateSearchResults(v);}));updateSearchResults(query);searchInput.requestFocus();searchInput.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(searchInput,InputMethodManager.SHOW_IMPLICIT),180);}
    void updateSearchResults(String query){if(searchResults==null)return;searchResults.removeAllViews();ScrollView scroll=new ScrollView(this);searchResults.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(18),dp(8),dp(18),dp(24));scroll.addView(list);boolean any=false;ArrayList<String> matchingLabels=new ArrayList<>();for(String label:labels){boolean hit=query==null||query.isEmpty()||contains(label,query);if(!hit)for(Note n:notes)if(noteMatchesQuery(n,query)&&n.tags.contains(label)){hit=true;break;}if(hit&&(activeTagFilter.isEmpty()||activeTagFilter.equals(label)))matchingLabels.add(label);}if(!matchingLabels.isEmpty()){TextView heading=text("标签",16,ink,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(36));list.addView(heading,hp);for(String label:matchingLabels){TextView tag=text("标签  ·  "+label+"    ›",14,ink,false);if(query!=null&&!query.isEmpty())tag.setText(highlight("标签  ·  "+label+"    ›",query));tag.setPadding(dp(12),0,dp(12),0);tag.setBackground(shape(Color.WHITE,14));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,dp(46));tp.bottomMargin=dp(8);list.addView(tag,tp);tag.setOnClickListener(v->{activeTagFilter=label;updateSearchResults(query);});}any=true;}TextView notesHead=text("笔记",16,ink,true);LinearLayout.LayoutParams nh=new LinearLayout.LayoutParams(-1,dp(42));nh.topMargin=dp(4);list.addView(notesHead,nh);ArrayList<Note> ordered=new ArrayList<>(notes);ordered.sort((a,b)->a.pinned==b.pinned?Long.compare(b.updatedAt,a.updatedAt):(a.pinned?-1:1));int count=0;for(Note n:ordered){boolean tagMatch=activeTagFilter.isEmpty()||n.tags.contains(activeTagFilter);if(tagMatch&&noteMatchesQuery(n,query)){addPreviewCard(list,n,query==null?"":query);count++;}}if(count==0&&!any)emptyHome(list,"没有找到相关笔记","试试更短的关键词。");}
    void buildMy(){screen=5;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(10),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));FrameLayout menu=iconButton("菜单",()->showDrawer());header.addView(menu,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView title=text("我的",20,ink,true);LinearLayout.LayoutParams titleParams=new LinearLayout.LayoutParams(0,-1,1);titleParams.leftMargin=dp(8);header.addView(title,titleParams);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(18),dp(20),dp(20));root.addView(content,new LinearLayout.LayoutParams(-1,0,1));TextView appearance=text("外观与阅读",16,ink,true);appearance.setPadding(dp(16),0,dp(16),0);appearance.setBackground(shape(Color.WHITE,12));content.addView(appearance,new LinearLayout.LayoutParams(-1,dp(58)));appearance.setOnClickListener(v->showAppearanceSettings());TextView export=text("导出笔记",16,ink,true);export.setPadding(dp(16),0,dp(16),0);export.setBackground(shape(Color.WHITE,12));LinearLayout.LayoutParams xp=new LinearLayout.LayoutParams(-1,dp(58));xp.topMargin=dp(12);content.addView(export,xp);export.setOnClickListener(v->exportBackup());TextView importButton=text("导入笔记",16,ink,true);importButton.setPadding(dp(16),0,dp(16),0);importButton.setBackground(shape(Color.WHITE,12));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,dp(58));ip.topMargin=dp(12);content.addView(importButton,ip);importButton.setOnClickListener(v->importBackup());bottomNav(3);}
