    void showAppearanceSettings(){Dialog dialog=new Dialog(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),dp(18),dp(20),dp(16));panel.setBackground(shape(Color.WHITE,20));LinearLayout heading=row();TextView title=text("外观与阅读",19,ink,true);heading.addView(title,new LinearLayout.LayoutParams(0,dp(38),1));TextView close=text("×",24,muted,false);close.setGravity(Gravity.CENTER);heading.addView(close,new LinearLayout.LayoutParams(dp(36),dp(38)));panel.addView(heading);close.setOnClickListener(v->dialog.dismiss());appearanceRow(panel,"主题",new String[]{"经典白","雾灰","浅绿"}[themeChoice],()->styledOptions("选择主题","应用到页面背景和文字",Arrays.asList("经典白","雾灰","浅绿"),index->{themeChoice=index;saveAppearance();dialog.dismiss();refreshAppearanceScreen();},"取消",null));appearanceRow(panel,"字体",new String[]{"系统","衬线","等宽"}[fontChoice],()->styledOptions("选择字体","应用到阅读与编辑文字",Arrays.asList("系统","衬线","等宽"),index->{fontChoice=index;saveAppearance();dialog.dismiss();refreshAppearanceScreen();},"取消",null));appearanceRow(panel,"字号",fontSizeLabels()[fontSizeIndex()],()->styledOptions("选择字号","调整应用内阅读文字大小",Arrays.asList(fontSizeLabels()),index->{fontScale=new float[]{.9f,1f,1.15f,1.3f}[index];saveAppearance();dialog.dismiss();refreshAppearanceScreen();},"取消",null));appearanceRow(panel,"方格样式",new String[]{"实线","点阵","无网格"}[gridChoice],()->styledOptions("选择方格样式","应用到方格笔记编辑区",Arrays.asList("实线","点阵","无网格"),index->{gridChoice=index;saveAppearance();dialog.dismiss();refreshAppearanceScreen();},"取消",null));dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}
    void refreshAppearanceScreen(){if(screen==5)buildMy();else if(screen==4)buildEditor();else if(screen==6)buildWalk();else if(screen==2)buildTimeline();else if(screen==3)buildSearch(searchInput.getText().toString());else buildHome();}
    void exportBackup(){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"碎忆笔记备份.json");startActivityForResult(intent,REQUEST_EXPORT);}
    JSONObject backupJson()throws Exception{JSONObject root=new JSONObject();root.put("format","suiyi-notes");root.put("version",1);JSONArray n=new JSONArray();for(Note item:notes)n.put(item.json());root.put("notes",n);JSONArray t=new JSONArray();for(Note item:trash)t.put(item.json());root.put("trash",t);root.put("labels",new JSONArray(labels));root.put("pinnedLabels",new JSONArray(pinnedLabels));JSONArray time=new JSONArray();for(TimeEntry item:timeline)time.put(item.json());root.put("timeline",time);return root;}
    void writeBackup(android.net.Uri uri){try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入文件");out.write(backupJson().toString(2).getBytes(StandardCharsets.UTF_8));out.flush();toast("笔记已导出");}catch(Exception e){toast("导出失败，请重试");}}
    void importBackup(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");startActivityForResult(intent,REQUEST_IMPORT);}
    void readBackup(android.net.Uri uri){try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法读取文件");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int length;while((length=in.read(buffer))!=-1)bytes.write(buffer,0,length);JSONObject data=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));if(!"suiyi-notes".equals(data.optString("format")))throw new JSONException("不支持的备份格式");JSONArray incoming=data.optJSONArray("notes");if(incoming==null)throw new JSONException("备份中没有笔记");ArrayList<Note> imported=new ArrayList<>();for(int i=0;i<incoming.length();i++)imported.add(new Note(incoming.getJSONObject(i)));JSONArray incomingTrash=data.optJSONArray("trash");ArrayList<Note> importedTrash=new ArrayList<>();if(incomingTrash!=null)for(int i=0;i<incomingTrash.length();i++)importedTrash.add(new Note(incomingTrash.getJSONObject(i)));JSONArray incomingLabels=data.optJSONArray("labels");if(incomingLabels!=null)for(int i=0;i<incomingLabels.length();i++){String label=incomingLabels.getString(i);if(!labels.contains(label))labels.add(label);}JSONArray incomingPins=data.optJSONArray("pinnedLabels");if(incomingPins!=null)for(int i=0;i<incomingPins.length();i++){String label=incomingPins.getString(i);if(labels.contains(label)&&!pinnedLabels.contains(label))pinnedLabels.add(label);}notes.addAll(0,imported);trash.addAll(0,importedTrash);JSONArray incomingTime=data.optJSONArray("timeline");if(incomingTime!=null)for(int i=0;i<incomingTime.length();i++)timeline.add(new TimeEntry(incomingTime.getJSONObject(i)));persist();buildMy();toast("已导入"+imported.size()+"篇笔记");}catch(Exception e){toast("导入失败：文件格式无效");}}
    void buildEditor(){screen=4;build();}
