        if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=text(subtitle,14,muted,false);sub.setGravity(Gravity.TOP);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(4);sp.bottomMargin=dp(12);panel.addView(sub,sp);}else{View gap=new View(this);panel.addView(gap,new LinearLayout.LayoutParams(1,dp(8)));}
