        if(primary!=null){TextView ok=text(primary,14,Color.WHITE,true);ok.setGravity(Gravity.CENTER);ok.setBackground(shape(ink,14));LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(0,-1,1);if(secondary!=null)op.leftMargin=dp(10);actions.addView(ok,op);ok.setOnClickListener(v->{dialog.dismiss();if(onPrimary!=null)onPrimary.run();});}
        dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=window.getAttributes();lp.dimAmount=.28f;window.setAttributes(lp);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),WindowManager.LayoutParams.WRAP_CONTENT);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),WindowManager.LayoutParams.WRAP_CONTENT);if(content instanceof EditText){EditText editor=(EditText)content;editor.requestFocus();editor.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(editor,InputMethodManager.SHOW_IMPLICIT),160);}
