    void styledOptions(String title,String subtitle,List<String> options,OptionAction selected,String secondary,Runnable secondaryAction){
        Dialog dialog=new Dialog(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(22),dp(20),dp(22),dp(18));panel.setBackground(shape(Color.WHITE,24));panel.setElevation(dp(8));LinearLayout heading=row();TextView headingText=text(title,20,ink,true);heading.addView(headingText,new LinearLayout.LayoutParams(0,dp(34),1));TextView close=text("×",24,muted,false);close.setGravity(Gravity.CENTER);heading.addView(close,new LinearLayout.LayoutParams(dp(34),dp(34)));panel.addView(heading);close.setOnClickListener(v->dialog.dismiss());if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=text(subtitle,14,muted,false);panel.addView(sub,new LinearLayout.LayoutParams(-1,dp(34)));}
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<options.size();i++){final int index=i;TextView item=text(options.get(i),15,ink,false);item.setPadding(dp(4),0,dp(4),0);list.addView(item,new LinearLayout.LayoutParams(-1,dp(48)));item.setOnClickListener(v->{dialog.dismiss();selected.run(index);});if(i<options.size()-1){View divider=new View(this);divider.setBackgroundColor(line);list.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}}scroll.addView(list);panel.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(dp(320),Math.max(dp(48),options.size()*dp(49)))));
        LinearLayout actions=row();actions.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(48));ap.topMargin=dp(14);panel.addView(actions,ap);if(secondary!=null){TextView extra=text(secondary,14,ink,true);extra.setGravity(Gravity.CENTER);extra.setBackground(shape(0xFFF1F1F1,14));actions.addView(extra,new LinearLayout.LayoutParams(0,-1,1));extra.setOnClickListener(v->{dialog.dismiss();secondaryAction.run();});}TextView done=text("完成",14,Color.WHITE,true);done.setGravity(Gravity.CENTER);done.setBackground(shape(ink,14));LinearLayout.LayoutParams dpms=new LinearLayout.LayoutParams(0,-1,1);if(secondary!=null)dpms.leftMargin=dp(10);actions.addView(done,dpms);done.setOnClickListener(v->dialog.dismiss());
        dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=window.getAttributes();lp.dimAmount=.28f;window.setAttributes(lp);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),WindowManager.LayoutParams.WRAP_CONTENT);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),WindowManager.LayoutParams.WRAP_CONTENT);
    }
    void styledConfirm(String title,String message,String secondary,Runnable cancel,String primary,Runnable confirm){TextView bodyText=text(message,15,muted,false);bodyText.setGravity(Gravity.TOP);bodyText.setPadding(0,0,0,dp(6));styledPanel(title,null,bodyText,secondary,cancel,primary,confirm);}
    EditText dialogInput(String hint,String value,int minLines){EditText input=new EditText(this);input.setTextSize(16);input.setTextColor(ink);input.setHintTextColor(0xFFB0B0B0);input.setGravity(Gravity.TOP|Gravity.START);input.setMinLines(minLines);input.setPadding(dp(14),dp(12),dp(14),dp(12));input.setBackground(shape(0xFFF7F7F7,16));input.setHint(hint);if(value!=null)input.setText(value);return input;}
    void build(){screen=4;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);toolbar();
        body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),0,dp(20),dp(10));root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
        tagLine();editorHint();content=new FrameLayout(this);body.addView(content,new LinearLayout.LayoutParams(-1,0,1));
        renderContent();bottomNav(0); }
    String dateKey(Calendar c){return String.format(Locale.US,"%04d-%02d-%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH));}
    String dateHeading(Calendar c){String[] weekdays={"周日","周一","周二","周三","周四","周五","周六"};return (c.get(Calendar.MONTH)+1)+"月"+c.get(Calendar.DAY_OF_MONTH)+"日  "+weekdays[c.get(Calendar.DAY_OF_WEEK)-1];}
    void buildTimeline(){screen=2;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(10),dp(18),dp(10));root.addView(header,new LinearLayout.LayoutParams(-1,dp(54)));FrameLayout menu=iconButton("菜单",()->showDrawer());header.addView(menu,new LinearLayout.LayoutParams(dp(42),dp(40)));TextView back=text("统计",20,ink,true);LinearLayout.LayoutParams backParams=new LinearLayout.LayoutParams(0,-1,1);backParams.leftMargin=dp(8);header.addView(back,backParams);String calendarIcon=calendarMode?"日历":"列表视图";FrameLayout cal=iconButton(calendarIcon,()->{calendarMode=!calendarMode;calendarCollapsed=false;buildTimeline();});header.addView(cal,new LinearLayout.LayoutParams(dp(42),dp(40)));if(calendarMode){FrameLayout collapse=iconButton(calendarCollapsed?"展开日历":"收起日历",()->{calendarCollapsed=!calendarCollapsed;buildTimeline();});collapse.setContentDescription(calendarCollapsed?"展开日历":"收起日历");header.addView(collapse,new LinearLayout.LayoutParams(dp(42),dp(40)));}
        if(calendarMode){if(calendarCollapsed)collapsedMonthBar();else monthCalendar();}else weekStrip();
        LinearLayout dayTitle=row();dayTitle.setPadding(dp(22),dp(10),dp(22),dp(6));root.addView(dayTitle,new LinearLayout.LayoutParams(-1,dp(52)));TextView date=text(dateHeading(selectedDate),18,ink,true);dayTitle.addView(date,new LinearLayout.LayoutParams(0,-1,1));TextView add=button("＋",()->editTimeline(-1));dayTitle.addView(add,new LinearLayout.LayoutParams(dp(48),dp(42)));
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout entries=new LinearLayout(this);entries.setOrientation(LinearLayout.VERTICAL);entries.setPadding(dp(18),dp(4),dp(18),dp(18));scroll.addView(entries);String selectedKey=dateKey(selectedDate);int count=0;
        ArrayList<Note> dayNotes=new ArrayList<>();for(Note n:notes)if(dateKeyForMillis(n.updatedAt).equals(selectedKey))dayNotes.add(n);dayNotes.sort((a,b)->Long.compare(b.updatedAt,a.updatedAt));for(Note n:dayNotes){addPreviewCard(entries,n,"");count++;}
        for(int i=timeline.size()-1;i>=0;i--){TimeEntry item=timeline.get(i);if(!item.date.equals(selectedKey))continue;count++;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(18),dp(16),dp(18),dp(14));card.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);entries.addView(card,cp);TextView contentText=text(item.content,15,ink,false);contentText.setGravity(Gravity.TOP);card.addView(contentText,new LinearLayout.LayoutParams(-1,-2));TextView timestamp=text(item.createdAt>0?timestampLabel(item.createdAt):item.date,12,0xFFB0B0B0,false);LinearLayout.LayoutParams timeParams=new LinearLayout.LayoutParams(-1,dp(22));timeParams.topMargin=dp(8);card.addView(timestamp,timeParams);TextView edit=text("编辑",13,muted,false);edit.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(28));ep.topMargin=dp(2);card.addView(edit,ep);card.setOnClickListener(v->editTimeline(timeline.indexOf(item)));card.setOnLongClickListener(v->{styledConfirm("删除记录","删除这条时间记录？","取消",null,"删除",()->{timeline.remove(item);persist();buildTimeline();});return true;});}
        if(count==0){TextView empty=text("这一天还没有记录",14,muted,false);empty.setGravity(Gravity.CENTER);entries.addView(empty,new LinearLayout.LayoutParams(-1,dp(120)));}
        bottomNav(1);}
    void buildWalk(){screen=6;refreshWalkNotes();root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(10),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));FrameLayout menu=iconButton("菜单",()->showDrawer());header.addView(menu,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView title=text("漫步",20,ink,true);LinearLayout.LayoutParams titleParams=new LinearLayout.LayoutParams(0,-1,1);titleParams.leftMargin=dp(8);header.addView(title,titleParams);FrameLayout filter=iconButton("筛选",this::showWalkFilter);filter.setContentDescription("筛选漫步范围");header.addView(filter,new LinearLayout.LayoutParams(dp(42),dp(42)));
        FrameLayout area=new FrameLayout(this);root.addView(area,new LinearLayout.LayoutParams(-1,0,1));if(walkNotes.isEmpty()){emptyHome(area,"还没有可漫步的笔记",walkFilterLabel());}else{Note item=walkNotes.get(Math.max(0,Math.min(walkIndex,walkNotes.size()-1)));LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(20),dp(22),dp(20),dp(18));area.addView(page,new FrameLayout.LayoutParams(-1,-1));TextView range=text(walkFilterLabel(),13,muted,false);page.addView(range,new LinearLayout.LayoutParams(-1,dp(28)));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(20),dp(20),dp(20),dp(20));card.setBackground(shape(themeChoice==0?Color.WHITE:themeChoice==1?0xFFF9F9FA:0xFFF9FCFA,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,0,1);cp.topMargin=dp(8);page.addView(card,cp);TextView date=text(dateLabel(item.updatedAt),13,muted,false);card.addView(date,new LinearLayout.LayoutParams(-1,dp(28)));TextView heading=text(item.title.trim().isEmpty()?"无标题":item.title,23,ink,true);heading.setPadding(0,dp(8),0,dp(8));card.addView(heading,new LinearLayout.LayoutParams(-1,dp(52)));TextView preview=text(preview(item),16,ink,false);preview.setGravity(Gravity.TOP);card.addView(preview,new LinearLayout.LayoutParams(-1,0,1));if(!item.tags.isEmpty()){TextView tags=text("标签  ·  "+displayTags(item.tags),13,muted,false);tags.setPadding(0,dp(12),0,0);card.addView(tags,new LinearLayout.LayoutParams(-1,dp(32)));}GestureDetector openGesture=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onDoubleTap(MotionEvent e){openNote(item,"");return true;}});card.setOnTouchListener((v,e)->openGesture.onTouchEvent(e));TextView counter=text((walkIndex+1)+" / "+walkNotes.size(),13,muted,false);counter.setGravity(Gravity.CENTER);page.addView(counter,new LinearLayout.LayoutParams(-1,dp(36)));}
        bottomNav(2);}
    void refreshWalkNotes(){walkNotes.clear();long now=System.currentTimeMillis();for(Note item:notes){boolean match=true;if(walkFilter==1)match=item.updatedAt>=now-7L*24*60*60*1000;if(walkFilter==2){Calendar c=Calendar.getInstance();c.setTimeInMillis(item.updatedAt);match=c.get(Calendar.YEAR)==walkMonth.get(Calendar.YEAR)&&c.get(Calendar.MONTH)==walkMonth.get(Calendar.MONTH);}if(match)walkNotes.add(item);}walkNotes.sort((a,b)->Long.compare(b.updatedAt,a.updatedAt));if(walkReturnNote!=null){int returnedIndex=walkNotes.indexOf(walkReturnNote);if(returnedIndex>=0)walkIndex=returnedIndex;walkReturnNote=null;}if(walkIndex>=walkNotes.size())walkIndex=Math.max(0,walkNotes.size()-1);}
    String walkFilterLabel(){if(walkFilter==1)return "近七天";if(walkFilter==2)return String.format(Locale.CHINA,"%d年%d月",walkMonth.get(Calendar.YEAR),walkMonth.get(Calendar.MONTH)+1);return "全部笔记";}
    void stepWalk(int delta){if(walkNotes.isEmpty())return;walkIndex=Math.max(0,Math.min(walkNotes.size()-1,walkIndex+delta));buildWalk();}
    void showWalkFilter(){styledOptions("漫步筛选","选择要浏览的笔记范围",Arrays.asList("全部","近七天","选择月份"),index->{if(index==0){walkFilter=0;walkIndex=0;buildWalk();}else if(index==1){walkFilter=1;walkIndex=0;buildWalk();}else showWalkMonthPicker();},"取消",null);}
    void showWalkMonthPicker(){TreeMap<String,String> months=new TreeMap<>(Collections.reverseOrder());for(Note item:notes){Calendar month=Calendar.getInstance();month.setTimeInMillis(item.updatedAt);String key=String.format(Locale.US,"%04d-%02d",month.get(Calendar.YEAR),month.get(Calendar.MONTH)+1);months.put(key,String.format(Locale.CHINA,"%d年%d月",month.get(Calendar.YEAR),month.get(Calendar.MONTH)+1));}if(months.isEmpty()){styledConfirm("选择月份","还没有可浏览的笔记。","取消",null,"完成",null);return;}ArrayList<String> keys=new ArrayList<>(months.keySet()),options=new ArrayList<>(months.values());styledOptions("选择月份","浏览指定月份的笔记",options,index->{walkMonth.set(Calendar.YEAR,Integer.parseInt(keys.get(index).substring(0,4)));walkMonth.set(Calendar.MONTH,Integer.parseInt(keys.get(index).substring(5))-1);walkFilter=2;walkIndex=0;buildWalk();},"取消",null);}
    boolean isToday(Calendar date){Calendar today=Calendar.getInstance();return dateKey(date).equals(dateKey(today));}
    String dateKeyForMillis(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);return dateKey(c);}
    int activityCount(Calendar day){String key=dateKey(day);int count=0;for(Note n:notes)if(dateKeyForMillis(n.updatedAt).equals(key))count++;for(TimeEntry e:timeline)if(e.date.equals(key))count++;return count;}
    int heatColor(int count){if(count<=0)return 0xFFF7F7F7;if(count==1)return 0xFFEDEDED;if(count==2)return 0xFFDFDFDF;if(count<=4)return 0xFFCECECE;return 0xFFB8B8B8;}
    void changeMonth(int delta){int day=selectedDate.get(Calendar.DAY_OF_MONTH);selectedDate.set(Calendar.DAY_OF_MONTH,1);selectedDate.add(Calendar.MONTH,delta);selectedDate.set(Calendar.DAY_OF_MONTH,Math.min(day,selectedDate.getActualMaximum(Calendar.DAY_OF_MONTH)));buildTimeline();}
    void collapsedMonthBar(){LinearLayout month=row();month.setPadding(dp(16),0,dp(16),0);TextView prev=text("‹",30,muted,false);prev.setGravity(Gravity.CENTER);month.addView(prev,new LinearLayout.LayoutParams(dp(48),dp(48)));prev.setOnClickListener(v->changeMonth(-1));TextView label=text(selectedDate.get(Calendar.YEAR)+"年"+(selectedDate.get(Calendar.MONTH)+1)+"月",18,ink,true);label.setGravity(Gravity.CENTER);month.addView(label,new LinearLayout.LayoutParams(0,dp(48),1));TextView next=text("›",30,muted,false);next.setGravity(Gravity.CENTER);month.addView(next,new LinearLayout.LayoutParams(dp(48),dp(48)));next.setOnClickListener(v->changeMonth(1));root.addView(month,new LinearLayout.LayoutParams(-1,dp(54)));}
    void weekStrip(){HorizontalScrollView h=new HorizontalScrollView(this);h.setHorizontalScrollBarEnabled(false);LinearLayout days=row();days.setGravity(Gravity.CENTER);h.addView(days);Calendar first=(Calendar)selectedDate.clone();int dow=first.get(Calendar.DAY_OF_WEEK);first.add(Calendar.DAY_OF_MONTH,-((dow+5)%7));String[] names={"周一","周二","周三","周四","周五","周六","周日"};for(int i=0;i<7;i++){Calendar d=(Calendar)first.clone();d.add(Calendar.DAY_OF_MONTH,i);boolean selected=dateKey(d).equals(dateKey(selectedDate)),today=isToday(d);int activeColor=today?0xFFE5E5E5:0xFFE44332;LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);item.setBackground(shape(selected?activeColor:Color.WHITE,18));int selectedText=selected?(today?ink:Color.WHITE):ink;TextView week=text(names[i],13,selected?(today?ink:Color.WHITE):muted,false);week.setGravity(Gravity.CENTER);TextView number=text(""+d.get(Calendar.DAY_OF_MONTH),18,selectedText,true);number.setGravity(Gravity.CENTER);item.addView(week);item.addView(number);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(56),dp(72));p.leftMargin=dp(4);p.rightMargin=dp(4);days.addView(item,p);item.setOnClickListener(v->{selectedDate=(Calendar)d.clone();buildTimeline();});}root.addView(h,new LinearLayout.LayoutParams(-1,dp(92)));}
    void monthCalendar(){LinearLayout month=row();month.setPadding(dp(16),0,dp(16),0);TextView prev=text("‹",34,muted,false);prev.setGravity(Gravity.CENTER);month.addView(prev,new LinearLayout.LayoutParams(dp(48),dp(48)));prev.setOnClickListener(v->changeMonth(-1));TextView label=text(selectedDate.get(Calendar.YEAR)+"年"+(selectedDate.get(Calendar.MONTH)+1)+"月",20,ink,true);label.setGravity(Gravity.CENTER);month.addView(label,new LinearLayout.LayoutParams(0,dp(48),1));TextView next=text("›",34,muted,false);next.setGravity(Gravity.CENTER);month.addView(next,new LinearLayout.LayoutParams(dp(48),dp(48)));next.setOnClickListener(v->changeMonth(1));root.addView(month,new LinearLayout.LayoutParams(-1,dp(54)));GridLayout grid=new GridLayout(this);grid.setColumnCount(7);grid.setPadding(dp(12),dp(2),dp(12),dp(4));String[] weekdays={"日","一","二","三","四","五","六"};for(int col=0;col<7;col++){TextView weekday=text(weekdays[col],13,muted,false);weekday.setGravity(Gravity.CENTER);GridLayout.LayoutParams head=new GridLayout.LayoutParams(GridLayout.spec(0),GridLayout.spec(col,1f));head.width=0;head.height=dp(28);grid.addView(weekday,head);}Calendar first=(Calendar)selectedDate.clone();first.set(Calendar.DAY_OF_MONTH,1);int offset=first.get(Calendar.DAY_OF_WEEK)-1;int total=first.getActualMaximum(Calendar.DAY_OF_MONTH);for(int i=0;i<42;i++){int day=i-offset+1;TextView cell=text(day>0&&day<=total?String.format(Locale.US,"%02d",day):"",14,ink,false);cell.setGravity(Gravity.CENTER);GridLayout.LayoutParams lp=new GridLayout.LayoutParams(GridLayout.spec(i/7+1),GridLayout.spec(i%7,1f));lp.width=0;lp.height=dp(42);grid.addView(cell,lp);if(day>0&&day<=total){Calendar chosen=(Calendar)selectedDate.clone();chosen.set(Calendar.DAY_OF_MONTH,day);boolean today=isToday(chosen),selected=dateKey(chosen).equals(dateKey(selectedDate));GradientDrawable cellBg=shape(selected&&!today?0xFF777777:heatColor(activityCount(chosen)),24);if(today)cellBg.setStroke(dp(2),selected?ink:0xFF777777);cell.setBackground(cellBg);if(selected&&!today)cell.setTextColor(Color.WHITE);else cell.setTextColor(ink);if(activityCount(chosen)>0)cell.setTypeface(null,1);cell.setOnClickListener(v->{selectedDate=(Calendar)chosen.clone();buildTimeline();});}}root.addView(grid,new LinearLayout.LayoutParams(-1,dp(282)));}
    boolean hasEntry(Calendar d){for(TimeEntry e:timeline)if(e.date.equals(dateKey(d)))return true;return false;}
    void editTimeline(int idx){TimeEntry old=idx>=0?timeline.get(idx):null;EditText input=dialogInput("记录今日时间使用感悟、待办完成情况…",old==null?"":old.content,5);input.setOnFocusChangeListener((v,has)->{if(has)input.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT),120);});input.requestFocus();String subtitle=old!=null&&old.createdAt>0?timestampLabel(old.createdAt):dateHeading(selectedDate);styledPanel(old==null?"记录今天":"编辑记录",subtitle,input,"取消",null,"保存",()->{String value=input.getText().toString().trim();if(value.isEmpty())return;if(old==null){Calendar recorded=(Calendar)selectedDate.clone(),now=Calendar.getInstance();recorded.set(Calendar.HOUR_OF_DAY,now.get(Calendar.HOUR_OF_DAY));recorded.set(Calendar.MINUTE,now.get(Calendar.MINUTE));recorded.set(Calendar.SECOND,now.get(Calendar.SECOND));recorded.set(Calendar.MILLISECOND,now.get(Calendar.MILLISECOND));timeline.add(new TimeEntry(dateKey(selectedDate),value,recorded.getTimeInMillis()));}else old.content=value;persist();buildTimeline();});}
    void toolbar(){top=row();top.setPadding(dp(16),dp(8),dp(12),dp(8));root.addView(top,new LinearLayout.LayoutParams(-1,dp(54)));FrameLayout hamburger=iconButton("菜单",()->showDrawer());top.addView(hamburger,new LinearLayout.LayoutParams(dp(42),dp(40)));
        if(screen==4){String title=note.title==null||note.title.trim().isEmpty()?"未命名":note.title;boolean unnamed=note.title==null||note.title.trim().isEmpty();TextView label=text(title,17,unnamed?muted:ink,true);label.setSingleLine(true);label.setMaxWidth(dp(150));label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setOnClickListener(v->editTitle());top.addView(label,new LinearLayout.LayoutParams(-2,-1));FrameLayout pencil=new FrameLayout(this);pencil.setContentDescription("编辑标题");TextView pencilGlyph=text("✎",21,muted,true);pencilGlyph.setGravity(Gravity.CENTER);pencil.addView(pencilGlyph,new FrameLayout.LayoutParams(-1,-1));pencil.setOnClickListener(v->editTitle());top.addView(pencil,new LinearLayout.LayoutParams(dp(34),dp(40)));View spacer=new View(this);top.addView(spacer,new LinearLayout.LayoutParams(0,1,1));FrameLayout undo=iconButton("撤销",this::undo);undo.setTag("editor-undo");styleUndoButton(undo);top.addView(undo,new LinearLayout.LayoutParams(dp(36),dp(40)));FrameLayout more=iconButton("更多",()->{});more.setOnClickListener(v->showMenu(more));top.addView(more,new LinearLayout.LayoutParams(dp(38),dp(40)));}
        else{TextView label=text(screen==0?"碎忆":screen==2?"统计":"搜索",18,ink,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.leftMargin=dp(8);top.addView(label,p);FrameLayout search=iconButton("搜索",()->openSearch(""));if(screen!=3)top.addView(search,new LinearLayout.LayoutParams(dp(42),dp(40)));FrameLayout more=iconButton("更多",()->{});more.setOnClickListener(v->showMenu(more));top.addView(more,new LinearLayout.LayoutParams(dp(42),dp(40)));}}
    void editTitle(){EditText input=dialogInput("未命名",note.title,1);styledPanel("编辑标题",null,input,"取消",null,"完成",()->{note.title=input.getText().toString().trim();note.updatedAt=System.currentTimeMillis();persist();build();});}
    void titleEditor(){titleInput=new EditText(this);EditText e=titleInput;e.setSingleLine(true);e.setTextSize(26);e.setTypeface(null,1);e.setTextColor(ink);e.setHintTextColor(170);e.setHint("未命名");e.setPadding(0,dp(16),0,dp(8));e.setBackgroundColor(Color.TRANSPARENT);e.setText(note.title);if(!pendingSearch.isEmpty())highlightEditor(e,pendingSearch);e.addTextChangedListener(watch(v->{note.title=v;note.updatedAt=System.currentTimeMillis();persist();}));body.addView(e,new LinearLayout.LayoutParams(-1,dp(58)));}
    interface StringChange{void change(String s);} TextWatcher watch(StringChange c){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){c.change(s.toString());}public void afterTextChanged(Editable e){}};}
    void tagLine(){LinearLayout r=row();r.setPadding(0,0,0,dp(6));body.addView(r);String selected=displayTags(note.tags);TextView tags=text(note.tags.isEmpty()?"没标签":"标签  ·  "+selected,13,muted,false);if(!pendingSearch.isEmpty())tags.setText(highlight(tags.getText().toString(),pendingSearch));r.addView(tags,new LinearLayout.LayoutParams(0,dp(32),1));tags.setOnClickListener(v->tagPicker());TextView add=text("＋ 添加标签",12,ink,true);add.setGravity(Gravity.CENTER);r.addView(add,new LinearLayout.LayoutParams(-2,dp(32)));add.setOnClickListener(v->tagPicker());}
    String displayLabel(String label){return label==null?"":label.replace("#","").trim();}
    String displayTags(List<String> source){StringBuilder out=new StringBuilder();for(String label:source){if(out.length()>0)out.append(" · ");out.append(displayLabel(label));}return out.toString();}
    void editorHint(){if(getPreferences(0).getBoolean("hideAssemblyHint",false))return;LinearLayout hint=row();FrameLayout info=new FrameLayout(this);info.setBackground(shape(0xFFF1F1F1,20));TextView i=text("i",13,muted,true);i.setGravity(Gravity.CENTER);info.addView(i,new FrameLayout.LayoutParams(-1,-1));hint.addView(info,new LinearLayout.LayoutParams(dp(22),dp(22)));TextView message=text("点击任意一格即可开始记录 · 点击反转按钮，进入文字组装界面",12,muted,false);message.setMaxLines(2);message.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(0,dp(42),1);mp.leftMargin=dp(8);hint.addView(message,mp);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(44));hp.bottomMargin=dp(2);body.addView(hint,hp);View.OnClickListener explain=v->showAssemblyHintChoice();info.setOnClickListener(explain);message.setOnClickListener(explain);}
    void showAssemblyHintChoice(){styledConfirm("操作提示","点击任意一格即可开始记录；点击反转按钮，进入文字组装界面。","取消",null,"不再提醒",()->{getPreferences(0).edit().putBoolean("hideAssemblyHint",true).apply();build();});}
    FrameLayout footerIcon(String name,String description,Runnable action){FrameLayout holder=new FrameLayout(this);holder.setContentDescription(description);holder.setBackground(shape(Color.WHITE,12));String symbol=name.equals("undo")?"↶":name.equals("plus")?"＋":"▣";TextView glyph=text(symbol,name.equals("plus")?28:25,ink,true);glyph.setGravity(Gravity.CENTER);holder.addView(glyph,new FrameLayout.LayoutParams(-1,-1));holder.setOnClickListener(v->action.run());if(name.equals("undo"))styleUndoButton(holder);return holder;}
    void styleUndoButton(View button){boolean enabled=!undo.isEmpty();button.setAlpha(enabled?1f:.38f);button.setEnabled(enabled);}
    void footer(){LinearLayout f=row();f.setTag("editor-footer");f.setPadding(dp(20),dp(8),dp(20),dp(12));f.setBackgroundColor(Color.WHITE);root.addView(f,new LinearLayout.LayoutParams(-1,dp(58)));
        FrameLayout undoBtn=footerIcon("undo","撤销",()->undo());f.addView(undoBtn,new LinearLayout.LayoutParams(dp(48),dp(42)));
        FrameLayout add=footerIcon("plus","记录片段",()->editBlock(-1));LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(0,dp(42),1);a.leftMargin=dp(12);a.rightMargin=dp(12);f.addView(add,a);
        FrameLayout copy=footerIcon("copy","复制全文",()->copyAll());f.addView(copy,new LinearLayout.LayoutParams(dp(48),dp(42)));}
    void renderContent(){content.removeAllViews();if(isLinear){linear=new EditText(this);linear.setGravity(Gravity.TOP|Gravity.START);linear.setTextSize(16*fontScale);linear.setTextColor(ink);linear.setHintTextColor(170);linear.setHint("把想起的内容写下来……");linear.setPadding(dp(16),dp(16),dp(16),dp(16));linear.setBackground(shape(themeChoice==0?Color.WHITE:themeChoice==1?0xFFF9F9FA:0xFFF9FCFA,18));if(fontChoice==1)linear.setTypeface(Typeface.SERIF);else if(fontChoice==2)linear.setTypeface(Typeface.MONOSPACE);linear.setText(note.text);if(!pendingSearch.isEmpty())highlightEditor(linear,pendingSearch);linear.addTextChangedListener(watch(v->{note.text=v;note.updatedAt=System.currentTimeMillis();persist();}));content.addView(linear,new FrameLayout.LayoutParams(-1,-1));}else{boardScroll=new ScrollView(this);boardScroll.setFillViewport(true);board=new Board();boardScroll.addView(board,new ScrollView.LayoutParams(-1,-2));content.addView(boardScroll,new FrameLayout.LayoutParams(-1,-1));if(!pendingSearch.isEmpty())highlightMatchingBlocks(pendingSearch);}FrameLayout mode=new FrameLayout(this);mode.setContentDescription(isLinear?"切换为方格":"切换为排版");mode.setBackground(shape(themeChoice==0?Color.WHITE:themeChoice==1?0xFFF9F9FA:0xFFF9FCFA,22));mode.setElevation(dp(2));TextView icon=text("⇄",20,ink,true);icon.setGravity(Gravity.CENTER);mode.addView(icon,new FrameLayout.LayoutParams(-1,-1));FrameLayout.LayoutParams modeParams=new FrameLayout.LayoutParams(dp(34),dp(34),Gravity.TOP|Gravity.RIGHT);modeParams.setMargins(0,dp(6),dp(6),0);content.addView(mode,modeParams);mode.setOnClickListener(v->toggleEditorMode());}
    void toggleEditorMode(){saveUndo();if(isLinear){String value=note.text==null?"":note.text;note.blocks.clear();if(!value.isEmpty()){Block block=new Block();block.text=value;block.order=0;note.blocks.add(block);}note.text="";isLinear=false;}else{note.text=note.blocksText();note.blocks.clear();isLinear=true;}note.updatedAt=System.currentTimeMillis();persist();build();}
    void highlightEditor(EditText editor,String query){String all=editor.getText().toString();int pos=all.toLowerCase(Locale.ROOT).indexOf(query.toLowerCase(Locale.ROOT));if(pos>=0){SpannableString span=new SpannableString(all);span.setSpan(new BackgroundColorSpan(0xFFFFE48A),pos,pos+query.length(),0);editor.setText(span);editor.setSelection(pos);editor.post(()->editor.bringPointIntoView(pos));}}
    void highlightMatchingBlocks(String query){for(Block b:note.blocks)if(contains(b.text,query)){boardScroll.post(()->boardScroll.smoothScrollTo(0,Math.max(0,(int)(b.y*board.cell)-dp(100))));break;}}
    void editBlock(int idx){editBlock(idx,0,nextY());}
    void editBlock(int idx,int startX,int startY){if(blockDialog!=null&&blockDialog.isShowing())return;final boolean existing=idx>=0;final Note owner=note;final Block old=existing?note.blocks.get(idx):new Block();if(!existing){old.x=startX;old.y=startY;old.order=nextBlockOrder();}saveUndo();EditText input=dialogInput("写下刚刚想起的内容…",old.text,4);Dialog dialog=new Dialog(this);blockDialog=dialog;LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(22),dp(20),dp(22),dp(18));panel.setBackground(shape(Color.WHITE,24));LinearLayout header=row();TextView heading=text(!existing?"记录片段":"编辑片段",20,ink,true);header.addView(heading,new LinearLayout.LayoutParams(0,dp(42),1));if(existing){FrameLayout split=new FrameLayout(this);split.setContentDescription("拆分片段");split.addView(new IconGlyph("split",ink),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));header.addView(split,new LinearLayout.LayoutParams(dp(42),dp(42)));split.setOnClickListener(v->{int cursor=Math.max(0,Math.min(input.getSelectionStart(),input.length()));String value=input.getText().toString();if(cursor<=0||cursor>=value.length()){toast("请把光标放在片段中间再拆分");return;}String left=value.substring(0,cursor),right=value.substring(cursor);styledConfirm("拆分片段","确定将光标前后内容分成两个方块片段吗？","取消",null,"确定",()->{dialog.dismiss();saveUndo();old.text=left;Block second=new Block();second.text=right;second.x=old.x;second.y=old.y+Math.max(1,old.h)+1;for(Block candidate:note.blocks)if(candidate.order>old.order)candidate.order++;second.order=old.order+1;note.blocks.add(Math.min(note.blocks.indexOf(old)+1,note.blocks.size()),second);normalizeBlockOrder();note.updatedAt=System.currentTimeMillis();persist();renderContent();});});TextView delete=text("删除",14,0xFFE44332,true);delete.setGravity(Gravity.CENTER);header.addView(delete,new LinearLayout.LayoutParams(dp(48),dp(42)));delete.setOnClickListener(v->{dialog.dismiss();deleteBlock(old);});}FrameLayout done=new FrameLayout(this);done.setContentDescription("保存");done.addView(new IconGlyph("check",ink),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));header.addView(done,new LinearLayout.LayoutParams(dp(42),dp(42)));panel.addView(header,new LinearLayout.LayoutParams(-1,dp(42)));input.setGravity(Gravity.TOP|Gravity.START);input.setMinLines(4);input.setPadding(dp(14),dp(16),dp(14),dp(16));input.setBackground(shape(0xFFF7F7F7,16));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,0,1);ip.topMargin=dp(12);panel.addView(input,ip);Runnable flush=()->{old.text=input.getText().toString();old.sized=false;if(!owner.blocks.contains(old)&&!old.text.isEmpty())owner.blocks.add(old);owner.updatedAt=System.currentTimeMillis();persist();if(pendingDiskSave!=null)saveHandler.removeCallbacks(pendingDiskSave);pendingDiskSave=()->{getSharedPreferences("suiyi",0).edit().commit();pendingDiskSave=null;};saveHandler.postDelayed(pendingDiskSave,400);};input.addTextChangedListener(watch(value->{flush.run();}));done.setOnClickListener(v->{flush.run();if(pendingDiskSave!=null){saveHandler.removeCallbacks(pendingDiskSave);pendingDiskSave=null;}getSharedPreferences("suiyi",0).edit().commit();dialog.dismiss();});dialog.setOnDismissListener(v->{if(blockDialog==dialog)blockDialog=null;if(note==owner&&screen==4)renderContent();});dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}dialog.show();if(window!=null){int screenHeight=getResources().getDisplayMetrics().heightPixels;window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),(int)(screenHeight*.5f));WindowManager.LayoutParams params=window.getAttributes();params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.y=(int)(screenHeight*.25f);window.setAttributes(params);}input.requestFocus();input.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT),160);}
    void deleteBlock(Block target){Note owner=note;int index=owner.blocks.indexOf(target);if(index<0)return;owner.blocks.remove(index);owner.updatedAt=System.currentTimeMillis();persist();if(note==owner&&screen==4)renderContent();showUndoSnackbar("已删除笔记",()->{owner.blocks.add(Math.min(index,owner.blocks.size()),target);owner.updatedAt=System.currentTimeMillis();persist();if(note==owner&&screen==4)renderContent();});}
    int nextY(){int y=0;for(Block b:note.blocks)y=Math.max(y,b.y+b.h);return y;}
    void normalizeBlockOrder(){ArrayList<Block> sorted=new ArrayList<>(note.blocks);sorted.sort((a,b)->Integer.compare(a.order,b.order));for(int i=0;i<sorted.size();i++)sorted.get(i).order=i;}
    int nextBlockOrder(){int next=0;for(Block b:note.blocks)next=Math.max(next,b.order+1);return next;}
    void saveUndo(){try{undo.push(note.json().toString());if(undo.size()>20)undo.removeLast();refreshUndoButtons();}catch(Exception ignored){}}
    void refreshUndoButtons(){if(screen!=4||root==null)return;FrameLayout contentUndo=root.findViewWithTag("editor-undo");if(contentUndo!=null)styleUndoButton(contentUndo);LinearLayout footer=root.findViewWithTag("editor-footer");if(footer!=null&&footer.getChildCount()>0)styleUndoButton(footer.getChildAt(0));}
    void undo(){if(undo.isEmpty())return;try{note=new Note(new JSONObject(undo.pop()));notes.set(current,note);persist();build();}catch(Exception ignored){}}
    void copyAll(){String s=isLinear?linear.getText().toString():note.blocksText();if(!isLinear)note.text=s;((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("碎忆",s));toast("已复制全文");}
    void showMenu(){String[] items={"复制全文",note.favorite?"取消收藏":"收藏笔记","转换为普通笔记","删除笔记"};Runnable[] actions={this::copyAll,()->{note.favorite=!note.favorite;persist();toast(note.favorite?"已收藏":"已取消收藏");},this::toggleEditorMode,this::trashNote};Dialog dialog=new Dialog(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),dp(18),dp(20),dp(18));panel.setBackground(shape(Color.WHITE,20));LinearLayout header=row();TextView title=text("笔记操作",19,ink,true);header.addView(title,new LinearLayout.LayoutParams(0,dp(38),1));TextView close=text("×",24,muted,false);close.setGravity(Gravity.CENTER);header.addView(close,new LinearLayout.LayoutParams(dp(38),dp(38)));close.setOnClickListener(v->dialog.dismiss());panel.addView(header);GridLayout grid=new GridLayout(this);grid.setColumnCount(2);grid.setPadding(0,dp(8),0,0);for(int i=0;i<items.length;i++){final int index=i;TextView option=text(items[i],15,index==3?0xFFE44332:ink,true);option.setGravity(Gravity.CENTER);option.setBackground(shape(index==3?0xFFFFF1F0:0xFFF3F3F3,10));GridLayout.LayoutParams lp=new GridLayout.LayoutParams(GridLayout.spec(i/2),GridLayout.spec(i%2,1f));lp.width=0;lp.height=dp(76);lp.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(option,lp);option.setOnClickListener(v->{dialog.dismiss();actions[index].run();});}panel.addView(grid,new LinearLayout.LayoutParams(-1,dp(172)));dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(40),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(40),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}
    void showMenu(View anchor){String[] items={"复制全文",note.favorite?"取消收藏":"收藏笔记","转换为普通笔记","删除笔记"};Runnable[] actions={this::copyAll,()->{note.favorite=!note.favorite;persist();toast(note.favorite?"已收藏":"已取消收藏");},this::toggleEditorMode,this::trashNote};LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(shape(Color.WHITE,14));panel.setElevation(dp(8));PopupWindow popup=new PopupWindow(panel,dp(228),WindowManager.LayoutParams.WRAP_CONTENT,true);popup.setBackgroundDrawable(shape(Color.WHITE,14));popup.setOutsideTouchable(true);popup.setElevation(dp(8));for(int i=0;i<items.length;i++){final int index=i;TextView row=text(items[i],15,index==3?0xFFE44332:ink,false);row.setPadding(dp(14),0,dp(10),0);panel.addView(row,new LinearLayout.LayoutParams(-1,dp(50)));row.setOnClickListener(v->{popup.dismiss();actions[index].run();});if(i<items.length-1){View divider=new View(this);divider.setBackgroundColor(line);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.leftMargin=dp(12);lp.rightMargin=dp(12);panel.addView(divider,lp);}}popup.showAsDropDown(anchor,anchor.getWidth()-dp(228),dp(2));}
    void trashNote(){Note removed=note;int oldIndex=notes.indexOf(removed);notes.remove(removed);trash.add(0,removed);if(notes.isEmpty()){note=new Note();current=0;}else{current=Math.min(current,notes.size()-1);note=notes.get(current);}persist();buildHome();showUndoSnackbar("已删除笔记",()->{trash.remove(removed);notes.add(Math.min(oldIndex,notes.size()),removed);current=notes.indexOf(removed);note=removed;persist();buildHome();});}
