    void showTagActions(View anchor,String label){boolean pinned=pinnedLabels.contains(label);String[] choices={pinned?"取消置顶":"置顶","新建标签","搜索标签","删除标签","删除标签及笔记"};Runnable[] actions={()->toggleTagPin(label),()->addLabel(false),()->showLabelPicker(false),()->styledConfirm("删除标签","删除“"+label+"”标签？相关笔记会保留。","取消",null,"删除标签",()->deleteTag(label)),()->styledConfirm("删除标签及笔记","删除“"+label+"”标签，并将使用此标签的笔记移入回收站？","取消",null,"删除",()->deleteTagAndNotes(label))};LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(shape(Color.WHITE,14));PopupWindow popup=new PopupWindow(panel,dp(224),WindowManager.LayoutParams.WRAP_CONTENT,true);popup.setBackgroundDrawable(shape(Color.WHITE,14));popup.setOutsideTouchable(true);popup.setElevation(dp(8));for(int i=0;i<choices.length;i++){final int index=i;TextView choice=text(choices[i],14,i==4?0xFFE44332:(i==0&&pinned?0xFFB7791F:ink),false);choice.setPadding(dp(12),0,dp(8),0);panel.addView(choice,new LinearLayout.LayoutParams(-1,dp(44)));choice.setOnClickListener(v->{popup.dismiss();actions[index].run();});if(i==2){View divider=new View(this);divider.setBackgroundColor(line);panel.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}}popup.showAsDropDown(anchor,anchor.getWidth()-dp(224),dp(2));}
    void refreshVisibleScreen(){if(screen==5)buildMy();else if(screen==6)buildWalk();else if(screen==4)build();else if(screen==3)buildSearch(searchInput.getText().toString());else if(screen==2)buildTimeline();else buildHome();}
    void deleteTag(String label){int index=labels.indexOf(label);if(index<0)return;boolean wasPinned=pinnedLabels.remove(label);ArrayList<Note> tagged=new ArrayList<>();for(Note item:notes)if(item.tags.remove(label))tagged.add(item);labels.remove(index);closeDrawer();persist();refreshVisibleScreen();showUndoSnackbar("已删除标签",()->{labels.add(Math.min(index,labels.size()),label);if(wasPinned)pinnedLabels.add(label);for(Note item:tagged)if(!item.tags.contains(label))item.tags.add(label);persist();refreshVisibleScreen();});}
    void deleteTagAndNotes(String label){int labelIndex=labels.indexOf(label);if(labelIndex<0)return;boolean wasPinned=pinnedLabels.remove(label);ArrayList<Note> removed=new ArrayList<>();HashMap<Note,Integer> positions=new HashMap<>();for(int i=notes.size()-1;i>=0;i--){Note item=notes.get(i);if(item.tags.contains(label)){positions.put(item,i);item.tags.remove(label);notes.remove(i);trash.add(0,item);removed.add(item);}}boolean currentRemoved=note!=null&&removed.contains(note);labels.remove(labelIndex);closeDrawer();if(currentRemoved){if(notes.isEmpty()){note=new Note();current=0;}else{current=0;note=notes.get(0);}}persist();if(screen==4&&currentRemoved)buildHome();else refreshVisibleScreen();showUndoSnackbar("已删除标签及笔记",()->{labels.add(Math.min(labelIndex,labels.size()),label);if(wasPinned)pinnedLabels.add(label);removed.sort((a,b)->Integer.compare(positions.get(a),positions.get(b)));for(Note item:removed){trash.remove(item);if(!item.tags.contains(label))item.tags.add(label);notes.add(Math.min(positions.get(item),notes.size()),item);}if(!removed.isEmpty()){note=removed.get(0);current=notes.indexOf(note);}persist();refreshVisibleScreen();});}
    void addLabel(){addLabel(screen==4);}
    void addLabel(boolean selectAfter){EditText e=dialogInput("标签名称",null,1);styledPanel("新建标签",null,e,"取消",null,"添加",()->{String s=e.getText().toString().trim();if(!s.isEmpty()&&!labels.contains(s)){labels.add(s);if(selectAfter&&!note.tags.contains(s))note.tags.add(s);persist();if(screen==4)build();else refreshVisibleScreen();}});}
    void showTrash(){if(trash.isEmpty()){styledConfirm("回收站","回收站是空的。",null,null,"完成",null);return;}ArrayList<String> names=new ArrayList<>();for(Note n:trash)names.add(n.title.isEmpty()?"无标题":n.title);styledOptions("回收站","点击笔记即可恢复",names,w->{Note restored=trash.remove(w);notes.add(0,restored);current=0;note=restored;persist();build();toast("笔记已恢复");},"清空回收站",()->styledConfirm("清空回收站","永久删除回收站中的全部笔记？","取消",null,"清空",()->{trash.clear();persist();}));}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    void persist(){try{JSONArray a=new JSONArray();for(Note n:notes)a.put(n.json());JSONArray t=new JSONArray();for(Note n:trash)t.put(n.json());JSONArray time=new JSONArray();for(TimeEntry e:timeline)time.put(e.json());getSharedPreferences("suiyi",0).edit().putString("notes",a.toString()).putString("trash",t.toString()).putString("labels",new JSONArray(labels).toString()).putString("pinnedLabels",new JSONArray(pinnedLabels).toString()).putString("timeline",time.toString()).apply();}catch(Exception ignored){}}
    void load(){try{SharedPreferences prefs=getSharedPreferences("suiyi",0);JSONArray a=new JSONArray(prefs.getString("notes","[]"));for(int i=0;i<a.length();i++)notes.add(new Note(a.getJSONObject(i)));JSONArray t=new JSONArray(prefs.getString("trash","[]"));for(int i=0;i<t.length();i++)trash.add(new Note(t.getJSONObject(i)));JSONArray l=new JSONArray(prefs.getString("labels","[]"));labels.clear();for(int i=0;i<l.length();i++)labels.add(l.getString(i));JSONArray pl=new JSONArray(prefs.getString("pinnedLabels","[]"));for(int i=0;i<pl.length();i++)pinnedLabels.add(pl.getString(i));JSONArray time=new JSONArray(prefs.getString("timeline","[]"));for(int i=0;i<time.length();i++)timeline.add(new TimeEntry(time.getJSONObject(i)));}catch(Exception ignored){}}
    class TimeEntry{String date,content;long createdAt;TimeEntry(String d,String c){this(d,c,0);}TimeEntry(String d,String c,long timestamp){date=d;content=c;createdAt=timestamp;}TimeEntry(JSONObject o){date=o.optString("date");content=o.optString("content");createdAt=o.optLong("createdAt",0);}JSONObject json()throws Exception{JSONObject o=new JSONObject();o.put("date",date);o.put("content",content);if(createdAt>0)o.put("createdAt",createdAt);return o;}}
